using Forjix.Api.Authorization;using Forjix.Application.Common;using Forjix.Application.Features.Purchases;using Microsoft.AspNetCore.Mvc;
namespace Forjix.Api.Controllers;
[ApiController,Route("api/purchases")]public sealed class PurchasesController(IPurchaseService service):ControllerBase{[HttpGet,RequirePermission(Permissions.PurchasesView)]public async Task<ActionResult<PagedPurchases>>Get(string? search,string? status,int page=1,int pageSize=20,CancellationToken ct=default)=>Ok(await service.GetPurchasesAsync(search,status,page,pageSize,ct));[HttpGet("{id:guid}"),RequirePermission(Permissions.PurchasesView)]public async Task<ActionResult<PurchaseView>>Get(Guid id,CancellationToken ct)=>Ok(await service.GetPurchaseAsync(id,ct));[HttpPost,RequirePermission(Permissions.PurchasesManage)]public async Task<ActionResult<PurchaseView>>Post(CreatePurchaseRequest request,CancellationToken ct)=>StatusCode(201,await service.CreatePurchaseAsync(request,ct));[HttpPost("{id:guid}/receive"),RequirePermission(Permissions.PurchasesReceive)]public async Task<ActionResult<PurchaseView>>Receive(Guid id,PurchaseActionRequest request,CancellationToken ct)=>Ok(await service.ReceiveAsync(id,request,ct));[HttpPost("{id:guid}/cancel"),RequirePermission(Permissions.PurchasesManage)]public async Task<ActionResult<PurchaseView>>Cancel(Guid id,PurchaseActionRequest request,CancellationToken ct)=>Ok(await service.CancelAsync(id,request,ct));}
